#!/usr/bin/env node
"""
{{name}} - {{description}}
"""
import { program } from 'commander';
import { name, version, description } from './package.json';

program
  .name(name)
  .description(description)
  .version(version);

program
  .command('hello [name]')
  .description('Say hello')
  .action((name = 'World') => {
    console.log(`Hello, ${name}! This is {{name}}`);
  });

program.parse();
